// Inlines migrations/*.sql into a TypeScript module.
//
// The .sql files are the single source of truth — iOS bundles them directly as
// resources, and this generated module is how web and Tauri get the same bytes
// without a filesystem at runtime. Regenerated by `npm run generate`, which is
// wired to `pretest` and `prepare`, and the output is gitignored: never edit it,
// and never let it be the thing you change to alter the schema.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const migrationsDir = join(root, "migrations");
const outFile = join(root, "src", "generated", "migrations.ts");

const files = readdirSync(migrationsDir).filter((f) => f.endsWith(".sql")).sort();

const seen = new Set();
const entries = files.map((file) => {
  const match = /^(\d+)_([a-z0-9_-]+)\.sql$/.exec(file);
  if (!match) {
    throw new Error(`Migration filename must be NNN_name.sql, got: ${file}`);
  }
  const version = Number(match[1]);
  if (seen.has(version)) throw new Error(`Duplicate migration version ${version}`);
  seen.add(version);
  return { version, name: match[2], sql: readFileSync(join(migrationsDir, file), "utf8") };
});

// Versions must be contiguous from 1, or a client that skipped a release could
// apply migrations out of order.
entries.forEach((entry, i) => {
  if (entry.version !== i + 1) {
    throw new Error(`Migration versions must be contiguous from 1; found ${entry.version} at position ${i + 1}`);
  }
});

const body = `// GENERATED BY scripts/bundle-migrations.mjs — DO NOT EDIT.
// Edit the .sql files in migrations/ and run \`npm run generate\`.
import type { Migration } from "../types.ts";

export const MIGRATIONS: readonly Migration[] = ${JSON.stringify(entries, null, 2)} as const;
`;

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, body);
console.log(`bundled ${entries.length} migration(s) -> src/generated/migrations.ts`);
